        case Id::FmtFloorSoloHint:
            return "\xD1\xEE\xE2\xE5\xF2: \xE2\xEA\xEB\xFE\xF7\xE8\xF2\xE5 \xEE\xE4\xE8\xED\xEE\xF7\xED\xFB\xE9 \xF0\xE5\xE6\xE8\xEC, \xEA\xEB\xE0\xE2\xE8\xF8\xE0 %s, \xE8\xED\xE0\xF7\xE5 \xF1\xEF\xF3\xF2\xED\xE8\xEA\xE8 \xF2\xEE\xE6\xE5 \xE1\xF3\xE4\xF3\xF2 \xED\xE0\xE6\xE8\xEC\xE0\xF2\xFC \xEF\xEB\xE8\xF2\xFB.";
        case Id::FloorPartyToggled:  return "\xD1\xEF\xF3\xF2\xED\xE8\xEA \xEF\xE5\xF0\xE5\xEA\xEB\xFE\xF7\xE8\xEB \xEF\xEB\xE8\xF2\xFB";
        case Id::FmtPlateName:       return "\xCF\xEB\xE8\xF2\xE0 %s";
        case Id::PlateCenterWord:    return "\xD6\xE5\xED\xF2\xF0";
        case Id::PlateResetName:     return "\xCF\xEB\xE8\xF2\xE0 \xF1\xE1\xF0\xEE\xF1\xE0";
        case Id::FmtPlateEntered:    return "\xC2\xFB \xED\xE0\xF1\xF2\xF3\xEF\xE8\xEB\xE8 \xED\xE0 %s";
        case Id::FmtPlateLit:        return "%s \xE7\xE0\xE3\xEE\xF0\xE0\xE5\xF2\xF1\xFF";
